conceptCard.exampleCode:
arr = [3, 1, 4, 1, 5]
n = len(arr)

# 버블 정렬: 이웃끼리 비교하며 교환
for i in range(n):
    for j in range(n - 1 - i):
        if arr[j] > arr[j + 1]:
            arr[j], arr[j + 1] = arr[j + 1], arr[j]
print(arr)  # [1, 1, 3, 4, 5]

